) VALUES (
    'manuel-feller-profile',
    '{"en": "Manuel Feller: Austria''s Slalom Showman", "de": "Manuel Feller: Österreichs Slalom-Showman", "fr": "Manuel Feller : Le showman autrichien du slalom", "it": "Manuel Feller: Lo showman austriaco dello slalom", "es": "Manuel Feller: El showman austriaco del eslalom", "pt": "Manuel Feller: O showman austríaco do slalom", "nl": "Manuel Feller: Oostenrijks slalom-showman", "ar": "مانويل فيلر: نجم التعرج النمساوي", "ja": "マヌエル・フェラー：オーストリアのスラロムスター", "zh": "Manuel Feller: Aodili Huixue Mingxing", "ko": "마누엘 펠러: 오스트리아 슬라럼 스타"}'::jsonb,
    '{"en": "The Austrian fan favorite brings personality and skill to every race. Known for his expressive celebrations and consistent podium finishes.", "de": "Der österreichische Publikumsliebling bringt Persönlichkeit und Können in jedes Rennen.", "fr": "Le favori du public autrichien apporte personnalité et talent à chaque course.", "it": "Il beniamino del pubblico austriaco porta personalità e abilità in ogni gara.", "es": "El favorito del público austriaco aporta personalidad y habilidad a cada carrera.", "pt": "O favorito do público austríaco traz personalidade e habilidade para cada corrida.", "nl": "De Oostenrijkse publiekslieveling brengt persoonlijkheid en vaardigheid naar elke race.", "ar": "المفضل لدى الجماهير النمساوية يجلب شخصيته ومهارته لكل سباق", "ja": "オーストリアのファンの人気者は、すべてのレースに個性とスキルをもたらします。", "zh": "Aodili de fensi zuiai, mei ci bisai dou zhanxian gexing he jineng.", "ko": "오스트리아 팬들의 사랑을 받는 선수로 모든 경기에 개성과 기술을 선보입니다."}'::jsonb,
    '{"en": "<p>Manuel Feller has become one of the most recognizable faces in World Cup <a href=\"/alpine-skiing-guide/\">alpine skiing</a>. The Austrian slalom specialist combines world-class technique with an expressive personality that makes him a fan favorite wherever he races.</p><h2>Career Highlights</h2><p>Feller has established himself as a consistent threat in technical events. His breakthrough came with multiple World Cup podiums in slalom, and he has shown he can compete with the very best on any course.</p><p>Known for his aggressive skiing style, Feller attacks every gate with full commitment. This approach has led to some spectacular victories and equally spectacular crashes - but fans love him for taking risks.</p><h2>Racing Style</h2><p>Feller''s technique stands out for its dynamic upper body movement and quick edge-to-edge transitions. He excels on steep, icy courses where his aggressive approach pays dividends.</p><p>His celebrations after good runs have become legendary in the sport. Win or podium, Feller always gives fans something to remember.</p><h2>Competition</h2><p>In slalom, Feller regularly battles against <a href=\"/clement-noel-profile/\">Clement Noel</a>, <a href=\"/henrik-kristoffersen-profile/\">Henrik Kristoffersen</a>, and <a href=\"/lucas-braathen-profile/\">Lucas Braathen</a>. The depth of talent in men''s slalom makes every race unpredictable.</p><h2>Looking Ahead</h2><p>Feller remains focused on winning major titles. With his combination of talent, experience, and personality, he continues to be one of the most exciting athletes in alpine skiing.</p>", "de": "<p>Manuel Feller ist zu einem der bekanntesten Gesichter im Weltcup-<a href=\"/alpine-skiing-guide/\">Ski Alpin</a> geworden. Der österreichische Slalomspezialist verbindet Weltklasse-Technik mit einer ausdrucksstarken Persönlichkeit.</p><h2>Karriere-Highlights</h2><p>Feller hat sich als konstante Bedrohung in technischen Disziplinen etabliert. Sein Durchbruch kam mit mehreren Weltcup-Podestplätzen im Slalom.</p><h2>Rennstil</h2><p>Fellers Technik zeichnet sich durch dynamische Oberkörperbewegungen und schnelle Kantenwechsel aus. Er brilliert auf steilen, eisigen Strecken.</p><h2>Konkurrenz</h2><p>Im Slalom kämpft Feller regelmäßig gegen <a href=\"/clement-noel-profile/\">Clement Noel</a>, <a href=\"/henrik-kristoffersen-profile/\">Henrik Kristoffersen</a> und <a href=\"/lucas-braathen-profile/\">Lucas Braathen</a>.</p>", "fr": "<p>Manuel Feller est devenu l''un des visages les plus reconnaissables du <a href=\"/alpine-skiing-guide/\">ski alpin</a> en Coupe du monde. Le spécialiste autrichien du slalom combine une technique de classe mondiale avec une personnalité expressive.</p><h2>Palmarès</h2><p>Feller s''est imposé comme une menace constante en technique. Sa percée est venue avec plusieurs podiums en Coupe du monde.</p><h2>Style de course</h2><p>La technique de Feller se distingue par des mouvements dynamiques du haut du corps et des transitions rapides.</p><h2>Concurrence</h2><p>En slalom, Feller affronte régulièrement <a href=\"/clement-noel-profile/\">Clement Noel</a> et <a href=\"/henrik-kristoffersen-profile/\">Henrik Kristoffersen</a>.</p>", "it": "<p>Manuel Feller è diventato uno dei volti più riconoscibili dello <a href=\"/alpine-skiing-guide/\">sci alpino</a> di Coppa del Mondo. Lo specialista austriaco dello slalom combina tecnica di classe mondiale con una personalità espressiva.</p><h2>Carriera</h2><p>Feller si è affermato come una minaccia costante nelle gare tecniche. La sua svolta è arrivata con diversi podi in Coppa del Mondo.</p><h2>Stile di gara</h2><p>La tecnica di Feller si distingue per i movimenti dinamici della parte superiore del corpo.</p><h2>Concorrenza</h2><p>Nello slalom, Feller si confronta regolarmente con <a href=\"/clement-noel-profile/\">Clement Noel</a> e <a href=\"/lucas-braathen-profile/\">Lucas Braathen</a>.</p>", "es": "<p>Manuel Feller se ha convertido en una de las caras más reconocibles del <a href=\"/alpine-skiing-guide/\">esquí alpino</a> de Copa del Mundo. El especialista austriaco en eslalom combina técnica de clase mundial con una personalidad expresiva.</p><h2>Carrera</h2><p>Feller se ha establecido como una amenaza constante en eventos técnicos.</p><h2>Estilo</h2><p>La técnica de Feller destaca por sus movimientos dinámicos del tren superior.</p>", "pt": "<p>Manuel Feller tornou-se um dos rostos mais reconhecíveis do <a href=\"/alpine-skiing-guide/\">esqui alpino</a> da Copa do Mundo. O especialista austríaco em slalom combina técnica de classe mundial com uma personalidade expressiva.</p><h2>Carreira</h2><p>Feller estabeleceu-se como uma ameaça constante em eventos técnicos.</p>", "nl": "<p>Manuel Feller is een van de meest herkenbare gezichten in de Wereldbeker <a href=\"/alpine-skiing-guide/\">alpine skiën</a> geworden. De Oostenrijkse slalomspecialist combineert wereldklasse techniek met een expressieve persoonlijkheid.</p><h2>Carrière</h2><p>Feller heeft zich gevestigd als een constante bedreiging in technische disciplines.</p>", "ar": "<p>أصبح مانويل فيلر أحد أشهر الوجوه في كأس العالم <a href=\"/alpine-skiing-guide/\">للتزلج الألبي</a>. يجمع المتخصص النمساوي في التعرج بين التقنية العالمية والشخصية المعبرة.</p><h2>أبرز المحطات</h2><p>أثبت فيلر نفسه كتهديد مستمر في السباقات التقنية.</p>", "ja": "<p>マヌエル・フェラーは、ワールドカップ<a href=\"/alpine-skiing-guide/\">アルペンスキー</a>で最も認知度の高い顔の一人となりました。オーストリアのスラロムスペシャリストは、世界クラスのテクニックと表現力豊かな個性を兼ね備えています。</p><h2>キャリアハイライト</h2><p>フェラーはテクニカル種目で常に脅威的な存在として確立しています。</p>", "zh": "<p>Manuel Feller yi chengwei Shijie Bei <a href=\"/alpine-skiing-guide/\">gaoshan huaxue</a> zhong zui zhiming de miankonng zhiyi. Zhe wei Aodili huixue zhuanjia jiehe le shijie ji jishu he biaoxianli.</p><h2>Zhiye liangdian</h2><p>Feller yi chengwei jishu xiangmu zhong de wending weixie.</p>", "ko": "<p>마누엘 펠러는 월드컵 <a href=\"/alpine-skiing-guide/\">알파인 스키</a>에서 가장 인지도 높은 얼굴 중 하나가 되었습니다. 오스트리아의 슬라럼 전문가는 세계적 수준의 기술과 표현력 있는 개성을 결합합니다.</p><h2>커리어 하이라이트</h2><p>펠러는 기술 종목에서 꾸준한 위협으로 자리잡았습니다.</p>"}'::jsonb,
    'athlete-profile',
